-- 529: Original BrillaPrep NSMQ subj_nsmq_biology true_false_problem_of_day beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_529_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_529_guard;
INSERT INTO _migration_529_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_pod_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_bio_genetics' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In humans, both parents have blood group AB. Using the ABO blood-group genetics, determine the probability that their child has blood group O.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '0% (impossible)' AND q.explanation IS 'Blood groups show codominance: group AB means genotype IᴬIᴮ. The cross IᴬIᴮ × IᴬIᴮ gives offspring genotypes IᴬIᴬ, IᴬIᴮ and IᴮIᴮ only. Group O requires the genotype ii, and neither parent carries an i allele, so the probability is zero.' AND q.difficulty IS 'hard' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_pod_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_529_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_pod_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_bio_physiology' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A student’s daily energy intake is 8400 kJ, of which the basal metabolic rate accounts for 70%. Calculate the energy available for physical activity and other processes.' AND q.question_type IS 'problem' AND q.round_type IS 'problem_of_day' AND q.options IS NULL AND q.correct_answer IS '2520 kJ' AND q.explanation IS 'Energy used by the basal metabolic rate = 70% × 8400 = 0.70 × 8400 = 5880 kJ. The remainder is available for activity: 8400 − 5880 = 2520 kJ. Basal metabolism covers essential processes such as maintaining body temperature and organ function at rest.' AND q.difficulty IS 'medium' AND q.points IS '5' AND q.marks IS '1' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_pod_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_529_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_tf_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_bio_genetics' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A gamete contains half the chromosome number found in a normal body cell of the same organism.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'Gametes are produced by meiosis, which halves the chromosome number, so they are haploid (n) while body cells are diploid (2n). Fertilisation of two gametes then restores the diploid number in the zygote.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_tf_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_529_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_tf_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_bio_ecology' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Energy is recycled between the trophic levels of an ecosystem.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'False' AND q.explanation IS 'Energy flows in one direction only: it is captured by producers and progressively lost as heat at each transfer, so it must be continually supplied by the Sun. It is nutrients such as carbon and nitrogen that are recycled.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_tf_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_529_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_tf_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_bio_physiology' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The hormone insulin lowers the concentration of glucose in the blood.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'Insulin is secreted by the pancreas when blood glucose rises; it stimulates liver and muscle cells to absorb glucose and convert it to glycogen for storage, thereby lowering blood glucose back towards the set point.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_tf_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_529_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_bio_tf_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_bio_biochemistry' AND q.subject_id IS 'subj_nsmq_biology' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Oxygen is released as a product of photosynthesis.' AND q.question_type IS 'true_false' AND q.round_type IS 'true_false' AND q.options IS NULL AND q.correct_answer IS 'True' AND q.explanation IS 'During the light-dependent stage of photosynthesis, water molecules are split (photolysis), releasing oxygen gas. The overall equation 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ shows oxygen as a product alongside glucose.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '10' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_bio_tf_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
